 spec fn cache_contents_of<K, V>(entries: alloc::collections::BTreeMap<K, CacheEntry<V>>) -> Map<K, V> {
     Map::new(
         |k: K| btreemap_view_spec(entries).dom().contains(k),
         |k: K| btreemap_view_spec(entries)[k].value,
     )
