     /// Cached entries.
     entries: BTreeMap<K, CacheEntry<V>>,
     /// Monotonically increasing counter for LRU ordering.
     counter: u64,
     /// Maximum number of entries.
     capacity: usize,
 }

 #[verus_verify]
