     }

     ///
     /// # Description
     ///
     /// Evicts the entry with the smallest `last_used` counter.
     ///
     #[verus_verify(external_body)]
     #[verus_spec(
         requires
             old(self)@.inv(),
             old(self)@.contents.dom().len() > 0,
         ensures
